#include <stdio.h>

int main() {
    // 长n -> 行数, 宽m -> 列数
    int n, m;
    scanf("%d %d", &n, &m);

    // 地图矩阵，这里把二维压缩为了一维
    int matrix[n][m];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            // 由于matrix是一维数组，所以这里(i, j)二维坐标也要转成一维坐标
            scanf("%d", &matrix[i][j]);
        }
    }

    if (matrix[0][0] == 1 || matrix[n - 1][m - 1] == 1) {
        puts("0");
        return 0;
    }

    long dp[n][m];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            dp[i][j] = 0;
        }
    }

    dp[0][0] = 1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (matrix[i][j] == 1) continue;

            if (i > 0) {
                dp[i][j] += dp[i - 1][j];
            }

            if (j > 0) {
                dp[i][j] += dp[i][j - 1];
            }
        }
    }

    printf("%ld\n", dp[n - 1][m - 1]);

    return 0;
}
